import { test, expect } from '@playwright/test';

test.describe('Table Row Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/table'); // Replace with the actual URL
  });

  test('should highlight selected rows in a different colour', async ({ page }) => {
    const firstRow = page.getByRole('row', { name: 'Row 1' });
    const secondRow = page.getByRole('row', { name: 'Row 2' });

    await firstRow.click();
    await expect(firstRow).toHaveCSS('background-color', 'rgb(255, 255, 0)'); // Replace with the actual highlight color

    await secondRow.click();
    await expect(secondRow).toHaveCSS('background-color', 'rgb(255, 255, 0)'); // Replace with the actual highlight color
  });

  test('should not highlight unselected rows', async ({ page }) => {
    const thirdRow = page.getByRole('row', { name: 'Row 3' });

    await expect(thirdRow).toHaveCSS('background-color', 'rgba(0, 0, 0, 0)'); // Replace with the actual default color
  });
});
